package dev.kali.labendicion.controller;

import com.google.api.client.googleapis.auth.oauth2.GoogleIdTokenVerifier;
import com.google.api.client.http.javanet.NetHttpTransport;
import com.google.api.client.json.JsonFactory;
import com.google.api.client.json.jackson2.JacksonFactory;
import dev.kali.labendicion.domain.entity.Usuario;
import dev.kali.labendicion.repository.UsuarioRepository;
import dev.kali.labendicion.service.RolService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import java.io.IOException;
import java.security.GeneralSecurityException;
import java.util.Collections;
import java.util.HashMap;
import java.util.Map;
import java.util.stream.Collectors;

@RestController
@RequestMapping("/api/auth")
@CrossOrigin(origins = {"http://localhost:5173", "http://localhost:5174", "https://labendicion.vercel.app", "https://labendicion-beta.vercel.app"})
public class AuthController {

    private static final String GOOGLE_CLIENT_ID = System.getenv("GOOGLE_CLIENT_ID") != null
        ? System.getenv("GOOGLE_CLIENT_ID")
        : "YOUR_GOOGLE_CLIENT_ID.apps.googleusercontent.com";

    @Autowired
    private UsuarioRepository usuarioRepository;

    @Autowired
    private RolService rolService;

    @PostMapping("/verify-google")
    public ResponseEntity<Map<String, Object>> verifyGoogleToken(@RequestBody Map<String, String> payload) {
        String idTokenString = payload.get("token");
        if (idTokenString == null || idTokenString.isBlank()) {
            return ResponseEntity.badRequest()
                .body(Collections.singletonMap("error", "Token no proporcionado"));
        }

        try {
            JsonFactory jsonFactory = JacksonFactory.getDefaultInstance();
            GoogleIdTokenVerifier verifier = new GoogleIdTokenVerifier.Builder(
                new NetHttpTransport(), jsonFactory)
                .setAudience(Collections.singletonList(GOOGLE_CLIENT_ID))
                .build();

            var idToken = verifier.verify(idTokenString);
            if (idToken != null) {
                var payload_data = idToken.getPayload();
                String email = payload_data.getEmail();
                String nombre = (String) payload_data.get("name");
                String fotoUrl = (String) payload_data.get("picture");
                String googleId = payload_data.getSubject();

                // Crear o actualizar usuario en BD
                Usuario usuario = usuarioRepository.findByEmail(email)
                    .orElseGet(() -> {
                        Usuario nuevoUsuario = Usuario.builder()
                            .email(email)
                            .nombre(nombre)
                            .fotoUrl(fotoUrl)
                            .googleId(googleId)
                            .activo(true)
                            .build();

                        Usuario usuarioGuardado = usuarioRepository.save(nuevoUsuario);

                        // Asignar rol por defecto según el email
                        try {
                            if ("cristian.san.garcia@gmail.com".equals(email)) {
                                rolService.asignarRolAUsuarioPorEmail(email, "SUPERADMINISTRADOR");
                            } else {
                                rolService.asignarRolAUsuarioPorEmail(email, "USUARIO");
                            }
                        } catch (Exception e) {
                            System.err.println("Error asignando rol inicial: " + e.getMessage());
                        }

                        return usuarioGuardado;
                    });

                // Verificar y asignar rol SUPERADMINISTRADOR si es el email específico
                if ("cristian.san.garcia@gmail.com".equals(email)) {
                    boolean tieneSuperAdmin = usuario.getRoles().stream()
                        .anyMatch(rol -> "SUPERADMINISTRADOR".equals(rol.getNombre()));

                    if (!tieneSuperAdmin) {
                        try {
                            rolService.asignarRolAUsuarioPorEmail(email, "SUPERADMINISTRADOR");
                            // Recargar usuario con el nuevo rol
                            usuario = usuarioRepository.findById(usuario.getId()).orElse(usuario);
                        } catch (Exception e) {
                            System.err.println("Error asignando rol SUPERADMINISTRADOR: " + e.getMessage());
                        }
                    }
                }

                // Actualizar último acceso
                usuario.setNombre(nombre);
                usuario.setFotoUrl(fotoUrl);
                usuarioRepository.save(usuario);

                // Preparar respuesta
                Map<String, Object> response = new HashMap<>();
                response.put("success", true);
                response.put("email", email);
                response.put("name", nombre);
                response.put("picture", fotoUrl);
                response.put("token", idTokenString);
                response.put("id", usuario.getId());
                response.put("roles", usuario.getRoles().stream()
                    .map(rol -> rol.getNombre())
                    .collect(Collectors.toList()));

                return ResponseEntity.ok(response);
            } else {
                return ResponseEntity.status(401)
                    .body(Collections.singletonMap("error", "Token inválido"));
            }
        } catch (GeneralSecurityException | IOException e) {
            return ResponseEntity.status(401)
                .body(Collections.singletonMap("error", "Error validando token: " + e.getMessage()));
        }
    }

    @PostMapping("/logout")
    public ResponseEntity<Map<String, String>> logout() {
        Map<String, String> response = new HashMap<>();
        response.put("message", "Sesión cerrada correctamente");
        return ResponseEntity.ok(response);
    }

    @GetMapping("/me")
    public ResponseEntity<Map<String, Object>> getCurrentUser() {
        Map<String, Object> response = new HashMap<>();
        response.put("authenticated", true);
        return ResponseEntity.ok(response);
    }

    @GetMapping("/debug/roles")
    public ResponseEntity<Map<String, Object>> debugRoles() {
        Map<String, Object> response = new HashMap<>();

        try {
            // Verificar si los roles existen
            var roles = rolService.obtenerTodosLosRoles();
            response.put("roles_count", roles.size());
            response.put("roles", roles.stream().map(rol -> Map.of(
                "id", rol.getId(),
                "nombre", rol.getNombre(),
                "permisos", rol.getPermisos().size()
            )).toList());

            // Verificar usuario específico
            var usuarioOpt = usuarioRepository.findByEmail("cristian.san.garcia@gmail.com");
            if (usuarioOpt.isPresent()) {
                var usuario = usuarioOpt.get();
                response.put("usuario_superadmin", Map.of(
                    "id", usuario.getId(),
                    "email", usuario.getEmail(),
                    "roles", usuario.getRoles().stream().map(rol -> rol.getNombre()).toList()
                ));
            } else {
                response.put("usuario_superadmin", "NO ENCONTRADO");
            }

            response.put("success", true);
        } catch (Exception e) {
            response.put("success", false);
            response.put("error", e.getMessage());
        }

        return ResponseEntity.ok(response);
    }
}

package dev.kali.labendicion.controller;

import dev.kali.labendicion.domain.entity.Rol;
import dev.kali.labendicion.domain.entity.Usuario;
import dev.kali.labendicion.repository.UsuarioRepository;
import dev.kali.labendicion.service.RolService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.HashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/roles")
@CrossOrigin(origins = {"http://localhost:5173", "http://localhost:5174", "https://labendicion.vercel.app", "https://labendicion-beta.vercel.app"})
public class RolController {

    @Autowired
    private RolService rolService;

    @Autowired
    private UsuarioRepository usuarioRepository;

    /**
     * Obtener todos los roles disponibles
     */
    @GetMapping
    public ResponseEntity<List<Rol>> obtenerRoles() {
        return ResponseEntity.ok(rolService.obtenerTodosLosRoles());
    }

    /**
     * Asignar un rol a un usuario por email
     * POST /api/roles/asignar
     * Body: {"email": "usuario@gmail.com", "nombreRol": "ADMINISTRADOR"}
     */
    @PostMapping("/asignar")
    public ResponseEntity<Map<String, Object>> asignarRol(@RequestBody Map<String, String> payload) {
        try {
            String email = payload.get("email");
            String nombreRol = payload.get("nombreRol");

            if (email == null || email.isBlank()) {
                Map<String, Object> error = new HashMap<>();
                error.put("error", "Email es requerido");
                return ResponseEntity.badRequest().body(error);
            }

            if (nombreRol == null || nombreRol.isBlank()) {
                Map<String, Object> error = new HashMap<>();
                error.put("error", "Nombre de rol es requerido");
                return ResponseEntity.badRequest().body(error);
            }

            rolService.asignarRolAUsuarioPorEmail(email, nombreRol);

            Usuario usuario = usuarioRepository.findByEmail(email).orElseThrow();

            Map<String, Object> response = new HashMap<>();
            response.put("success", true);
            response.put("mensaje", "Rol asignado correctamente");
            response.put("usuario", Map.of(
                "email", usuario.getEmail(),
                "nombre", usuario.getNombre(),
                "roles", usuario.getRoles().stream()
                    .map(Rol::getNombre)
                    .toList()
            ));

            return ResponseEntity.ok(response);
        } catch (RuntimeException e) {
            Map<String, Object> error = new HashMap<>();
            error.put("error", e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
    }

    /**
     * Remover un rol de un usuario por email
     * DELETE /api/roles/remover
     * Body: {"email": "usuario@gmail.com", "nombreRol": "ADMINISTRADOR"}
     */
    @PostMapping("/remover")
    public ResponseEntity<Map<String, Object>> removerRol(@RequestBody Map<String, String> payload) {
        try {
            String email = payload.get("email");
            String nombreRol = payload.get("nombreRol");

            if (email == null || email.isBlank()) {
                Map<String, Object> error = new HashMap<>();
                error.put("error", "Email es requerido");
                return ResponseEntity.badRequest().body(error);
            }

            Usuario usuario = usuarioRepository.findByEmail(email)
                .orElseThrow(() -> new RuntimeException("Usuario no encontrado"));

            Rol rol = rolService.obtenerRolPorNombre(nombreRol)
                .orElseThrow(() -> new RuntimeException("Rol no encontrado"));

            usuario.removerRol(rol);
            usuarioRepository.save(usuario);

            Map<String, Object> response = new HashMap<>();
            response.put("success", true);
            response.put("mensaje", "Rol removido correctamente");
            response.put("usuario", Map.of(
                "email", usuario.getEmail(),
                "nombre", usuario.getNombre(),
                "roles", usuario.getRoles().stream()
                    .map(Rol::getNombre)
                    .toList()
            ));

            return ResponseEntity.ok(response);
        } catch (RuntimeException e) {
            Map<String, Object> error = new HashMap<>();
            error.put("error", e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
    }

    /**
     * Obtener información de un usuario incluyendo sus roles
     * GET /api/roles/usuario?email=usuario@gmail.com
     */
    @GetMapping("/usuario")
    public ResponseEntity<Map<String, Object>> obtenerUsuario(@RequestParam String email) {
        try {
            Usuario usuario = usuarioRepository.findByEmail(email)
                .orElseThrow(() -> new RuntimeException("Usuario no encontrado"));

            Map<String, Object> response = new HashMap<>();
            response.put("id", usuario.getId());
            response.put("email", usuario.getEmail());
            response.put("nombre", usuario.getNombre());
            response.put("fotoUrl", usuario.getFotoUrl());
            response.put("activo", usuario.getActivo());
            response.put("roles", usuario.getRoles().stream()
                .map(Rol::getNombre)
                .toList());

            return ResponseEntity.ok(response);
        } catch (RuntimeException e) {
            Map<String, Object> error = new HashMap<>();
            error.put("error", e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
    }

    /**
     * Verificar si un usuario tiene un permiso específico
     * GET /api/roles/tiene-permiso?email=usuario@gmail.com&permiso=VER_PRODUCCION
     */
    @GetMapping("/tiene-permiso")
    public ResponseEntity<Map<String, Object>> tienePermiso(
            @RequestParam String email,
            @RequestParam String permiso) {
        try {
            Usuario usuario = usuarioRepository.findByEmail(email)
                .orElseThrow(() -> new RuntimeException("Usuario no encontrado"));

            boolean tienePermiso = rolService.usuarioTienePermiso(usuario.getId(), permiso);

            Map<String, Object> response = new HashMap<>();
            response.put("email", email);
            response.put("permiso", permiso);
            response.put("tienePermiso", tienePermiso);

            return ResponseEntity.ok(response);
        } catch (RuntimeException e) {
            Map<String, Object> error = new HashMap<>();
            error.put("error", e.getMessage());
            return ResponseEntity.badRequest().body(error);
        }
    }
}

package dev.kali.labendicion.domain.entity;

import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
@Entity
@Table(name = "permiso")
public class Permiso {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(unique = true, nullable = false)
    private String nombre;

    private String descripcion;

    // Categorías para organizar permisos
    @Column(nullable = false)
    private String categoria; // PRODUCCION, EMPLEADOS, ASEO, REPORTES, ROLES, etc.
}

package dev.kali.labendicion.domain.entity;

import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.util.HashSet;
import java.util.Set;

@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
@Entity
@Table(name = "rol")
public class Rol {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(unique = true, nullable = false)
    private String nombre;

    private String descripcion;

    @ManyToMany(fetch = FetchType.EAGER, cascade = CascadeType.DETACH)
    @JoinTable(
        name = "rol_permiso",
        joinColumns = @JoinColumn(name = "rol_id"),
        inverseJoinColumns = @JoinColumn(name = "permiso_id")
    )
    private Set<Permiso> permisos = new HashSet<>();

    public void agregarPermiso(Permiso permiso) {
        permisos.add(permiso);
    }

    public void removerPermiso(Permiso permiso) {
        permisos.remove(permiso);
    }

    public boolean tienePermiso(String nombrePermiso) {
        return permisos.stream()
            .anyMatch(permiso -> permiso.getNombre().equals(nombrePermiso));
    }
}

package dev.kali.labendicion.domain.entity;

import jakarta.persistence.*;
import jakarta.validation.constraints.Email;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.LocalDateTime;
import java.util.HashSet;
import java.util.Set;

@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
@Entity
@Table(name = "usuario")
public class Usuario {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(unique = true, nullable = false)
    @Email
    private String email;

    private String nombre;
    private String fotoUrl;

    @Column(unique = true)
    private String googleId;

    private Boolean activo = true;

    @Column(nullable = false, columnDefinition = "TIMESTAMP DEFAULT CURRENT_TIMESTAMP")
    private LocalDateTime fechaRegistro;

    private LocalDateTime ultimoAcceso;

    @ManyToMany(fetch = FetchType.EAGER, cascade = CascadeType.DETACH)
    @JoinTable(
        name = "usuario_rol",
        joinColumns = @JoinColumn(name = "usuario_id"),
        inverseJoinColumns = @JoinColumn(name = "rol_id")
    )
    private Set<Rol> roles = new HashSet<>();

    @PrePersist
    protected void onCreate() {
        if (fechaRegistro == null) {
            fechaRegistro = LocalDateTime.now();
        }
        if (activo == null) {
            activo = true;
        }
    }

    @PreUpdate
    protected void onUpdate() {
        ultimoAcceso = LocalDateTime.now();
    }

    public void agregarRol(Rol rol) {
        roles.add(rol);
    }

    public void removerRol(Rol rol) {
        roles.remove(rol);
    }

    public boolean tieneRol(String nombreRol) {
        return roles.stream()
            .anyMatch(rol -> rol.getNombre().equals(nombreRol));
    }
}

package dev.kali.labendicion.entity;

