import React, { createContext, useContext, useState, ReactNode } from 'react';

interface AuthContextType {
  isAuthenticated: boolean;
  user: AuthUser | null;
  token: string | null;
  roles: string[];
  login: (googleToken: string, user: AuthUser, roles: string[]) => void;
  logout: () => void;
  setToken: (token: string) => void;
  tieneRol: (nombreRol: string) => boolean;
  tienePermiso: (nombrePermiso: string) => boolean;
}

export interface AuthUser {
  id?: number;
  email: string;
  name: string;
  picture: string;
  roles?: string[];
}

const AuthContext = createContext<AuthContextType | undefined>(undefined);

export const AuthProvider = ({ children }: { children: ReactNode }) => {
  const [isAuthenticated, setIsAuthenticated] = useState(() => {
    return !!localStorage.getItem('authToken');
  });

  const [user, setUser] = useState<AuthUser | null>(() => {
    const storedUser = localStorage.getItem('authUser');
    return storedUser ? JSON.parse(storedUser) : null;
  });

  const [token, setTokenState] = useState<string | null>(() => {
    return localStorage.getItem('authToken');
  });

  const [roles, setRoles] = useState<string[]>(() => {
    const storedRoles = localStorage.getItem('authRoles');
    return storedRoles ? JSON.parse(storedRoles) : [];
  });

  const login = (googleToken: string, authUser: AuthUser, userRoles: string[] = []) => {
    localStorage.setItem('authToken', googleToken);
    localStorage.setItem('authUser', JSON.stringify(authUser));
    localStorage.setItem('authRoles', JSON.stringify(userRoles));
    setTokenState(googleToken);
    setUser(authUser);
    setRoles(userRoles);
    setIsAuthenticated(true);
  };

  const logout = () => {
    localStorage.removeItem('authToken');
    localStorage.removeItem('authUser');
    localStorage.removeItem('authRoles');
    setTokenState(null);
    setUser(null);
    setRoles([]);
    setIsAuthenticated(false);
  };

  const setToken = (newToken: string) => {
    localStorage.setItem('authToken', newToken);
    setTokenState(newToken);
  };

  const tieneRol = (nombreRol: string): boolean => {
    return roles.includes(nombreRol);
  };

  const tienePermiso = (nombrePermiso: string): boolean => {
    // Por ahora, implementaremos esto en el backend
    // En el frontend solo verificamos roles
    return true; // Implementar lógica de permisos si es necesario
  };

  return (
    <AuthContext.Provider value={{ isAuthenticated, user, token, roles, login, logout, setToken, tieneRol, tienePermiso }}>
      {children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) throw new Error('useAuth debe usarse dentro de un AuthProvider');
  return context;
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router';
// @ts-ignore
import { GoogleLogin, CredentialResponse } from '@react-oauth/google';
import { useAuth } from '../context/AuthContext';

const API_BASE = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8080';

export const Login = () => {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [error, setError] = useState('');

  const handleSuccess = async (credentialResponse: CredentialResponse) => {
    try {
      setError('');
      const response = await fetch(`${API_BASE}/api/auth/verify-google`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token: credentialResponse.credential }),
      });

      if (!response.ok) {
        throw new Error('Error en autenticación');
      }

      const data = await response.json();
      login(credentialResponse.credential as string, {
        email: data.email,
        name: data.name,
        picture: data.picture,
      });
      navigate('/');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error de autenticación');
    }
  };

  return (
    <div className='min-h-screen bg-gradient-to-br from-teal-50 to-blue-50 flex items-center justify-center'>
      <div className='bg-white rounded-2xl shadow-xl p-8 max-w-md w-full'>
        <h1 className='text-3xl font-bold text-center text-teal-900 mb-4'>La Bendición</h1>
        <p className='text-center text-slate-600 mb-6 text-sm'>Sistema de Gestión Textil</p>

        {error && (
          <div className='bg-red-50 border border-red-200 text-red-700 p-3 rounded mb-4 text-sm'>
            {error}
          </div>
        )}

        <div className='flex justify-center'>
          <GoogleLogin
            onSuccess={handleSuccess}
            onError={() => setError('Error al conectar con Google')}
          />
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { useNavigate } from 'react-router';
// @ts-ignore
import { GoogleLogin, CredentialResponse } from '@react-oauth/google';
import { useAuth } from '../context/AuthContext';

const API_BASE = import.meta.env.VITE_API_BASE_URL || 'http://localhost:8080';

export const Login = () => {
  const navigate = useNavigate();
  const { login } = useAuth();
  const [error, setError] = useState('');

  const handleSuccess = async (credentialResponse: CredentialResponse) => {
    try {
      setError('');
      const response = await fetch(`${API_BASE}/api/auth/verify-google`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token: credentialResponse.credential }),
      });

      if (!response.ok) {
        throw new Error('Error en autenticación');
      }

      const data = await response.json();
      login(credentialResponse.credential as string, {
        id: data.id,
        email: data.email,
        name: data.name,
        picture: data.picture,
      }, data.roles || []);
      navigate('/');
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error de autenticación');
    }
  };

  return (
    <div className='min-h-screen bg-gradient-to-br from-teal-50 to-blue-50 flex items-center justify-center'>
      <div className='bg-white rounded-2xl shadow-xl p-8 max-w-md w-full'>
        <h1 className='text-3xl font-bold text-center text-teal-900 mb-4'>La Bendición</h1>
        <p className='text-center text-slate-600 mb-6 text-sm'>Sistema de Gestión Textil</p>

        {error && (
          <div className='bg-red-50 border border-red-200 text-red-700 p-3 rounded mb-4 text-sm'>
            {error}
          </div>
        )}

        <div className='flex justify-center'>
          <GoogleLogin
            onSuccess={handleSuccess}
            onError={() => setError('Error al conectar con Google')}
          />
        </div>
      </div>
    </div>
  );
};

import { createBrowserRouter, Navigate } from "react-router";
import { Layout } from "./components/Layout";
import { Home } from "./pages/Home";
import { Produccion } from "./pages/Produccion";
import { Empleados } from "./pages/Empleados";
import { Aseo } from "./pages/Aseo";
import { Rendimiento } from "./pages/Rendimiento";
import { Login } from "./pages/Login";

const ProtectedRoute = ({ Component }: { Component: React.FC }) => {
  const token = localStorage.getItem('authToken');
  return token ? <Component /> : <Navigate to="/login" replace />;
};

export const router = createBrowserRouter([
  { path: "/login", Component: Login },
  {
    path: "/",
    Component: Layout,
    children: [
      { index: true, Component: () => <ProtectedRoute Component={Home} /> },
      { path: "produccion", Component: () => <ProtectedRoute Component={Produccion} /> },
      { path: "empleados", Component: () => <ProtectedRoute Component={Empleados} /> },
      { path: "aseo", Component: () => <ProtectedRoute Component={Aseo} /> },
      { path: "rendimiento", Component: () => <ProtectedRoute Component={Rendimiento} /> },
    ],
  },
]);

import { createBrowserRouter } from "react-router";
import { Layout } from "./components/Layout";
import { ProtectedRoute } from "./components/ProtectedRoute";
import { Home } from "./pages/Home";
import { Produccion } from "./pages/Produccion";
import { Empleados } from "./pages/Empleados";
import { Aseo } from "./pages/Aseo";
import { Rendimiento } from "./pages/Rendimiento";
import { Login } from "./pages/Login";
import { GestionarRoles } from "./components/GestionarRoles";

export const router = createBrowserRouter([
  { path: "/login", Component: Login },
  {
    path: "/",
    Component: Layout,
    children: [
      { index: true, Component: () => <ProtectedRoute><Home /></ProtectedRoute> },
      { path: "produccion", Component: () => <ProtectedRoute requiredRoles={['SUPERADMINISTRADOR', 'ADMINISTRADOR']}><Produccion /></ProtectedRoute> },
      { path: "empleados", Component: () => <ProtectedRoute requiredRoles={['SUPERADMINISTRADOR', 'ADMINISTRADOR']}><Empleados /></ProtectedRoute> },
      { path: "aseo", Component: () => <ProtectedRoute requiredRoles={['SUPERADMINISTRADOR', 'ADMINISTRADOR', 'TRABAJADOR']}><Aseo /></ProtectedRoute> },
      { path: "rendimiento", Component: () => <ProtectedRoute requiredRoles={['SUPERADMINISTRADOR', 'ADMINISTRADOR', 'TRABAJADOR']}><Rendimiento /></ProtectedRoute> },
      { path: "roles", Component: () => <ProtectedRoute requiredRoles={['SUPERADMINISTRADOR', 'ADMINISTRADOR']}><GestionarRoles /></ProtectedRoute> },
    ],
  },
]);

import { defineConfig } from 'vite'
import path from 'path'
import react from '@vitejs/plugin-react'
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

function figmaAssetResolver() {
  return {
    name: 'figma-asset-resolver',
    resolveId(id) {
      if (id.startsWith('figma:asset/')) {
        const filename = id.replace('figma:asset/', '')
        return path.resolve(__dirname, 'src/assets', filename)
      }
    },
  }
}

export default defineConfig({
  server: {
    proxy: {
      // Mismo origen que el dev server de Vite: el frontend usa /api/frontend por defecto
      '/api': {
        target: 'http://127.0.0.1:8080',
        changeOrigin: true,
      },
    },
  },
  plugins: [
    figmaAssetResolver(),
    react(),
  ],
  resolve: {
    alias: {
      // Alias @ to the src directory
      '@': path.resolve(__dirname, './src'),
    },
  },

  // File types to support raw imports. Never add .css, .tsx, or .ts files to this.
  assetsInclude: ['**/*.svg', '**/*.csv'],
  // @ts-expect-error Vitest test config
  test: {
    environment: 'jsdom',
    globals: true,
    setupFiles: './src/test/setup.ts',
    css: true,
  },
})

